#!/usr/bin/env bash
# write_sheng_manifest.sh
# ─────────────────────────────────────────────────────────────────────
# Write the authentic-CS manifest for the Sheng Swahili-English corpus
# at /workspace/data/secondary/code_switched/syntheticsentences.jsonl
#
# Origin defaults to "authentic" (genuine Sheng); change to "synthetic"
# if you confirm the file was generated by an LLM rather than collected
# from real Sheng sources.

set -e

MANIFEST_DIR=/workspace/data/corpus/manifests/authentic_code_switched
mkdir -p "$MANIFEST_DIR"

FILE="$MANIFEST_DIR/swahili_sheng_v1.yaml"

cat > "$FILE" <<'YAML'
source_id: swahili_sheng_v1
display_name: "Sheng Swahili-English code-switched corpus (religious register)"
origin: authentic
register: code_switched
language: swahili

location:
  type: jsonl
  path: /workspace/data/secondary/code_switched/syntheticsentences.jsonl
  text_field: text

collection:
  method: "External Sheng (Swahili-English code-switching) corpus; content appears to be biblical/religious material rendered in Sheng."
  date: 2026-05-16
  source_url: "https://drive.google.com/file/d/17Bz2rgpP9fng1U2Mf2H63O-5al4nqyMu/view"
  notes: |
    Filename `syntheticsentences.jsonl` is misleading; content is genuine Sheng
    code-switching, not LLM output. Code-switching is heavy at both function-word
    level (na, ya, ku, alafu) and content-word level (roof, mat, temple, stones,
    listen, do, get). Cultural and religious references are Kenyan-specific.
    If the file is later confirmed to be LLM-generated, change `origin` from
    "authentic" to "synthetic" in this manifest.

license:
  type: "unknown_internal_use_only"
  reuse_terms: "Origin license unverified; treat as research-only until clarified with data provider"

defaults:
  domain: religious
  code_switch_pair: swahili-english
  register_detail: sheng
  preprocessing:
    - unicode_nfc
    - whitespace_normalise
  augmentation: []

provenance_notes: |
  Sheng is the urban Kenyan Swahili-English code-switching register, used
  particularly in Nairobi and other urban centres. This corpus provides
  authentic CS data that the synthetic LughaGen pipeline could not reliably
  produce (see synth_separation_qa.json). Heavy CS rates (mean English-marker
  ratio typically 0.10-0.25 per sentence).

quality_contract:
  min_words: 5
  max_words: 500
  max_repetition_ratio: 0.50
  required_fields: [text]

records_at_ingest:
  count_source: 183049
YAML

echo "wrote $FILE"
echo
echo "Verify:"
echo "  cat $FILE"
echo
echo "If this file is actually LLM-generated synthetic CS (not authentic Sheng),"
echo "change 'origin: authentic' to 'origin: synthetic' in the manifest."
